+func buildTypeSharingLanguages(groups [][]string) map[string]map[string]bool {
+	compatible := map[string]map[string]bool{}
+	for _, group := range groups {
+		for _, a := range group {
+			for _, b := range group {
+				if a == b {
+					continue
+				}
