}

var jsonMarshalerType = reflect.TypeOf((*json.Marshaler)(nil)).Elem()

// reachableJSONMarshalerTypes returns named types whose value or pointer method
// set can replace encoding/json's ordinary reflected representation. A value
// receiver is reported once as T (even though *T inherits that method); a
// pointer-only receiver is reported as *T.
func reachableJSONMarshalerTypes(root reflect.Type) []string {
	var found []string
	walkPersistedJSONTypes(root, func(t reflect.Type) {
		if t.Name() == "" {
			return
		}
		if t.Implements(jsonMarshalerType) {
			found = append(found, t.String())
			return
