var wireMarshalerInterfaces = []struct {
	name string
	typ  reflect.Type
}{
	{name: "json.Marshaler", typ: reflect.TypeOf((*json.Marshaler)(nil)).Elem()},
	{name: "encoding.TextMarshaler", typ: reflect.TypeOf((*encoding.TextMarshaler)(nil)).Elem()},
