func TestJSONWireShapeFreezesAnonymousAndExplicitNameStatus(t *testing.T) {
	t.Parallel()
	for _, test := range []struct {
		name  string
		value any
		want  []string
	}{
		{
			name:  "anonymous",
			value: anonymousShapeFieldProbe{},
			want:  []string{`name="AnonymousShapeChildProbe" type="sem.AnonymousShapeChildProbe" tagged=false anonymous=true options=""`},
		},
