			want:  []string{`name="AnonymousShapeChildProbe" type="sem.AnonymousShapeChildProbe" tagged=false anonymous=false options=""`},
		},
		{
			name:  "anonymous with explicit default name",
			value: explicitlyNamedAnonymousShapeFieldProbe{},
