		},
		{
			name:  "named",
			value: namedShapeFieldProbe{},
			want:  []string{`name="AnonymousShapeChildProbe" type="github.com/entireio/entire-graph/internal/sem.AnonymousShapeChildProbe" tagged=false anonymous=false options=""`},
		},
		{
